import{_ as a,o,c as r,a2 as d}from"./chunks/framework.C4u7U0Dw.js";const p=JSON.parse('{"title":"第 1 章 初识 momawork-rs","description":"","frontmatter":{},"headers":[],"relativePath":"bluebook/第一篇 使用手册：先把我用起来/第 1 章 初识 momawork-rs.md","filePath":"bluebook/第一篇 使用手册：先把我用起来/第 1 章 初识 momawork-rs.md"}'),e={name:"bluebook/第一篇 使用手册：先把我用起来/第 1 章 初识 momawork-rs.md"};function l(s,t,i,n,h,m){return o(),r("div",null,[...t[0]||(t[0]=[d(`<h1 id="第-1-章-初识-momawork-rs" tabindex="-1">第 1 章 初识 momawork-rs <a class="header-anchor" href="#第-1-章-初识-momawork-rs" aria-label="Permalink to &quot;第 1 章 初识 momawork-rs&quot;">​</a></h1><h2 id="_1-1-我是谁" tabindex="-1">1.1 我是谁 <a class="header-anchor" href="#_1-1-我是谁" aria-label="Permalink to &quot;1.1 我是谁&quot;">​</a></h2><p>我是 <strong>momawork-rs</strong>，一个运行在 MomaWork 里的 AI 工作助手。你可以把我想象成一个<strong>坐在你电脑里的同事</strong>：</p><ul><li>我读得懂你的文件，改得了你的代码；</li><li>我会用命令行，能跑脚本、查目录、执行程序；</li><li>我在同一个项目里干活，工作目录就是你的工作目录；</li><li>我有持久记忆，下次见面我还记得你的偏好；</li><li>我一个人忙不过来时，还能拉一支 AI 团队。</li></ul><p>但我也不是万能的。明确边界，才能合作愉快。</p><h2 id="_1-2-我能做什么" tabindex="-1">1.2 我能做什么 <a class="header-anchor" href="#_1-2-我能做什么" aria-label="Permalink to &quot;1.2 我能做什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td>读写文件</td><td>创建、编辑、查看项目文件</td><td>写报告、改配置、读日志</td></tr><tr><td>执行命令</td><td>在 shell 里跑命令</td><td>装依赖、跑测试、批量处理</td></tr><tr><td>搜索定位</td><td>按文件名或内容找东西</td><td>找函数、搜报错、查文档</td></tr><tr><td>调用 Skill</td><td>加载预设的专业能力</td><td>提交代码、评审 PR、处理 PDF</td></tr><tr><td>记忆系统</td><td>持久保存用户与项目上下文</td><td>记住你的偏好和项目背景</td></tr><tr><td>计划模式</td><td>先规划再执行的长任务</td><td>大重构、多步骤交付</td></tr><tr><td>AI 团队</td><td>多智能体并行协作</td><td>开发+测试+文档并行</td></tr><tr><td>子代理</td><td>后台并行处理子任务</td><td>并行调研、分块生成</td></tr></tbody></table><h2 id="_1-3-我的边界-诚实版" tabindex="-1">1.3 我的边界（诚实版） <a class="header-anchor" href="#_1-3-我的边界-诚实版" aria-label="Permalink to &quot;1.3 我的边界（诚实版）&quot;">​</a></h2><ul><li><strong>我生活在你的工作目录里</strong>：我看不到你整个硬盘，只能访问当前项目及相关路径。</li><li><strong>网络访问有限</strong>：我不能随意浏览互联网，除非通过你提供的工具或下载链接。</li><li><strong>执行有风险的操作前，我会先确认</strong>：尤其是删除、覆盖、推送远程仓库这类不可逆动作。</li><li><strong>我的记忆是文件</strong>：存在你项目对应的 memory 目录里，你可以查看、修改、删除。</li><li><strong>我可能出错</strong>：所以重要任务，请让我给你&quot;可检查的中间产物&quot;，而不是只给结论。</li></ul><h2 id="_1-4-一次成功的合作是什么样" tabindex="-1">1.4 一次成功的合作是什么样 <a class="header-anchor" href="#_1-4-一次成功的合作是什么样" aria-label="Permalink to &quot;1.4 一次成功的合作是什么样&quot;">​</a></h2><p>一个好的 AI 任务，长这样：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你：写一份《Q3 运营复盘》，数据在 data/ 目录下，用模板 docs/template.md</span></span>
<span class="line"><span>我：先读模板和数据 → 问清口径 → 生成草稿 → 你检查 → 我修订 → 交付</span></span></code></pre></div><p>关键不是&quot;我说了什么&quot;，而是<strong>每一步都可检查、可回退</strong>。</p><h2 id="_1-5-练习" tabindex="-1">1.5 练习 <a class="header-anchor" href="#_1-5-练习" aria-label="Permalink to &quot;1.5 练习&quot;">​</a></h2><ol><li>对我说：&quot;你好，介绍一下你自己，以及你现在的工作目录。&quot;</li><li>让我列出当前工作目录里的文件清单（Glob 或 ls）。</li><li>告诉我你最近想解决的一个真实问题，我们把它变成第一个任务。</li></ol><blockquote><p>小结：我是一台&quot;任务执行器&quot;，不是&quot;聊天机器&quot;。你的表达越接近任务（有目标、有输入、有验收标准），我的输出就越接近交付物。</p></blockquote>`,16)])])}const _=a(e,[["render",l]]);export{p as __pageData,_ as default};
